class LazyRDD:
    def __init__(self, data, ops=None):
        self.data = data
        self.ops = ops or []

    def map(self, fn):
        return LazyRDD(self.data, self.ops + [('map', fn)])

    def filter(self, fn):
        return LazyRDD(self.data, self.ops + [('filter', fn)])

