def build_and_run():
    log = []
    def double(x):
        log.append(f'map {x}')
        return x * 2
    def over_five(x):
        log.append(f'filter {x}')
        return x > 5

    rdd = LazyRDD([1, 2, 3, 4, 5])
    transformed = rdd.map(double).filter(over_five)
    before_collect = len(log)
    result = transformed.collect()
    after_collect = len(log)
    return (before_collect, after_collect, result)
